import pandas as pd


def _is_null(x):
    try:
        return pd.isna(x)
    except (TypeError, ValueError):
        return x is None


def _differs(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_store = inputs["DIM_STORE"].copy()
    stg = inputs["STG_STORE_FULL"]
    batch_control = inputs["BATCH_CONTROL"]

    cols = ["store_id", "region", "format", "eff_start_date", "eff_end_date", "is_current"]

    # make sure output has the right columns, preserving existing dtypes where possible
    out = dim_store.copy()
    for c in cols:
        if c not in out.columns:
            out[c] = pd.NA

    # batch date (single row control table)
    b = batch_control["batch_date"].iloc[0]

    # distinct store rows from the full snapshot
    S = stg[["store_id", "region", "format"]].drop_duplicates().reset_index(drop=True)

    # map store_id -> index of its current (is_current == 1) row in out, if any
    current_mask = out["is_current"] == 1
    current_idx_map = {}
    for idx, row in out[current_mask].iterrows():
        current_idx_map[row["store_id"]] = idx

    S_store_ids = set(S["store_id"].tolist())

    new_rows = []

    for _, s in S.iterrows():
        store_id = s["store_id"]
        region = s["region"]
        fmt = s["format"]

        if store_id in current_idx_map:
            idx = current_idx_map[store_id]
            c_region = out.at[idx, "region"]
            c_format = out.at[idx, "format"]

            if _differs(c_region, region) or _differs(c_format, fmt):
                # close current version
                out.at[idx, "eff_end_date"] = b
                out.at[idx, "is_current"] = 0

                # open new version
                new_rows.append({
                    "store_id": store_id,
                    "region": region,
                    "format": fmt,
                    "eff_start_date": b,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                })
            # else: no-op, attributes match current row
        else:
            # brand-new store OR reactivated previously-closed store
            new_rows.append({
                "store_id": store_id,
                "region": region,
                "format": fmt,
                "eff_start_date": b,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })

    # close current rows for stores no longer present in the snapshot
    for store_id, idx in current_idx_map.items():
        if store_id not in S_store_ids:
            out.at[idx, "eff_end_date"] = b
            out.at[idx, "is_current"] = 0

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=cols)
        out = pd.concat([out, new_df], ignore_index=True)

    out = out[cols]

    return {"dim_store_out": out}
